        center: {
          u: (basePiece.center.u ?? 0) + deltaCenter.u,
          v: (basePiece.center.v ?? 0) + deltaCenter.v,
        },
      },
    };
  });

  return {
    ...dragDiff,
    pieces: {
      ...dragDiff.pieces,
      updated: nextUpdated,
    },
  };
}

